/**
 * O bigode do gato — porte de `componentes/viz/bigode_gato.js`.
 *
 * As vibrissas têm quase a largura do corpo: são uma régua viva. Se elas passam
 * pela fresta, o gato passa; se dobram, ele já sabe que não cabe — e nem tenta.
 * O ponto exato do módulo é o limite: a fresta em que os bigodes tocam as duas
 * bordas sem dobrar.
 */

import { criarCanvas2d } from '../../../viz/canvas2d.ts';
import {
  type EstadoDaViz,
  infoDe,
  limitar,
  numeroDe,
  paleta,
  rodape,
  texto,
  titulo,
} from './desenho.ts';
import type { FabricaViz, VizDoPuzzle } from './index.ts';

const bigodeGato: FabricaViz = (canvas): VizDoPuzzle => {
  let estado: EstadoDaViz = {};

  function desenhar(ctx: CanvasRenderingContext2D, L: number, A: number): void {
    const cor = paleta();
    const info = infoDe(estado);
    const valores = (estado.valores ?? {}) as Readonly<Record<string, unknown>>;

    const fresta = Math.max(0, numeroDe(valores, 'g', 0));
    const alvo = numeroDe(info, 'alvo', 50);
    const ok = info.ok === true;
    const cabe = fresta >= alvo;

    titulo(ctx, L, A, 'A régua que ele carrega no rosto');

    const cx = L * 0.5;
    const meiaFresta = (fresta / 100) * (L * 0.42);
    // A cota mora entre o título e o topo da parede. Estava em A·0,12, que é
    // exatamente onde o título é desenhado — os dois textos se sobrepunham.
    const yCota = A * 0.21;
    const paredeTopo = A * 0.26;
    const paredeBase = A * 0.9;

    // As duas paredes, com a fresta entre elas.
    ctx.fillStyle = '#8a7a66';
    ctx.fillRect(0, paredeTopo, cx - meiaFresta, paredeBase - paredeTopo);
    ctx.fillRect(cx + meiaFresta, paredeTopo, L - (cx + meiaFresta), paredeBase - paredeTopo);
    ctx.fillStyle = '#6b5c4a';
    ctx.fillRect(cx - meiaFresta - 4, paredeTopo, 4, paredeBase - paredeTopo);
    ctx.fillRect(cx + meiaFresta, paredeTopo, 4, paredeBase - paredeTopo);

    // A cota da fresta, com as marcas nas duas pontas.
    const miudo = limitar(A * 0.04, 9, 13);
    ctx.strokeStyle = cor.fraco;
    ctx.lineWidth = 1.2;
    ctx.beginPath();
    ctx.moveTo(cx - meiaFresta, yCota - 4);
    ctx.lineTo(cx - meiaFresta, yCota + 4);
    ctx.moveTo(cx + meiaFresta, yCota - 4);
    ctx.lineTo(cx + meiaFresta, yCota + 4);
    ctx.stroke();
    ctx.setLineDash([3, 3]);
    ctx.beginPath();
    ctx.moveTo(cx - meiaFresta, yCota);
    ctx.lineTo(cx + meiaFresta, yCota);
    ctx.stroke();
    ctx.setLineDash([]);
    texto(ctx, `${fresta} cm`, cx, yCota - miudo, miudo, { cor: cor.fraco, peso: 700 });

    // O gato. Os bigodes têm a meia-largura do corpo — o `alvo` é essa medida.
    const cabecaY = A * 0.66;
    const raio = limitar(Math.min(L, A) * 0.105, 22, 42);
    const vao = (alvo / 100) * (L * 0.42);
    const dobra = !cabe;

    ctx.strokeStyle = dobra ? cor.erro : cor.texto;
    ctx.lineWidth = Math.max(1.5, raio * 0.07);
    ctx.lineCap = 'round';
    for (const lado of [-1, 1]) {
      for (let k = 0; k < 3; k++) {
        const y = cabecaY - raio * 0.2 + k * raio * 0.25;
        const alcance = dobra ? Math.min(vao, meiaFresta) : vao;
        const bx = cx + lado * alcance;
        // Ao bater na parede, o bigode não some: ele DOBRA — que é o sinal.
        const by = dobra ? y - (vao - alcance) * 0.5 : y;

        ctx.beginPath();
        ctx.moveTo(cx + lado * raio * 0.7, y);
        ctx.quadraticCurveTo(cx + lado * alcance * 0.6, y - 2, bx, by);
        ctx.stroke();
      }
    }

    // ── O gato ────────────────────────────────────────────────────────────
    // Era uma bola com dois triângulos: orelhas por dentro, focinho, boca,
    // pupilas e listras dão um bicho em vez de um ícone — e o rosto é o
    // instrumento de medida do módulo, então vale desenhá-lo.
    const PELO = '#8b7f70';
    const PELO_ESCURO = '#6f6558';
    const ROSA = '#d98aa0';

    // O peito, aparecendo sob a cabeça: sem ele o gato flutua.
    ctx.fillStyle = PELO_ESCURO;
    ctx.beginPath();
    ctx.ellipse(cx, cabecaY + raio * 1.5, raio * 0.95, raio * 0.85, 0, 0, Math.PI * 2);
    ctx.fill();

    for (const lado of [-1, 1]) {
      // A orelha, e o pavilhão rosa dentro dela.
      ctx.fillStyle = PELO;
      ctx.beginPath();
      ctx.moveTo(cx + lado * raio * 0.82, cabecaY - raio * 0.5);
      ctx.lineTo(cx + lado * raio * 0.52, cabecaY - raio * 1.35);
      ctx.lineTo(cx + lado * raio * 0.08, cabecaY - raio * 0.72);
      ctx.closePath();
      ctx.fill();

      ctx.fillStyle = ROSA;
      ctx.beginPath();
      ctx.moveTo(cx + lado * raio * 0.66, cabecaY - raio * 0.6);
      ctx.lineTo(cx + lado * raio * 0.5, cabecaY - raio * 1.12);
      ctx.lineTo(cx + lado * raio * 0.26, cabecaY - raio * 0.72);
      ctx.closePath();
      ctx.fill();
    }

    ctx.fillStyle = PELO;
    ctx.beginPath();
    ctx.ellipse(cx, cabecaY, raio * 1.05, raio, 0, 0, Math.PI * 2);
    ctx.fill();

    // As listras da testa.
    ctx.strokeStyle = PELO_ESCURO;
    ctx.lineWidth = Math.max(1.4, raio * 0.08);
    ctx.lineCap = 'round';
    for (const dx of [-0.3, 0, 0.3]) {
      ctx.beginPath();
      ctx.moveTo(cx + raio * dx, cabecaY - raio * 0.85);
      ctx.lineTo(cx + raio * dx * 1.5, cabecaY - raio * 0.45);
      ctx.stroke();
    }

    // Os olhos, com a pupila em fenda — o traço que diz "gato".
    for (const lado of [-1, 1]) {
      const olhoX = cx + lado * raio * 0.4;
      const olhoY = cabecaY - raio * 0.1;

      ctx.fillStyle = ok ? cor.verde : '#cfe0a0';
      ctx.beginPath();
      ctx.ellipse(olhoX, olhoY, raio * 0.24, raio * 0.2, 0, 0, Math.PI * 2);
      ctx.fill();

      ctx.fillStyle = cor.texto;
      ctx.beginPath();
      ctx.ellipse(olhoX, olhoY, raio * 0.07, raio * 0.17, 0, 0, Math.PI * 2);
      ctx.fill();

      ctx.fillStyle = 'rgb(255 255 255 / 80%)';
      ctx.beginPath();
      ctx.arc(olhoX - raio * 0.09, olhoY - raio * 0.08, raio * 0.05, 0, Math.PI * 2);
      ctx.fill();
    }

    // As bochechas, o focinho e a boca em duplo arco.
    ctx.fillStyle = 'rgb(255 255 255 / 22%)';
    for (const lado of [-1, 1]) {
      ctx.beginPath();
      ctx.ellipse(
        cx + lado * raio * 0.3,
        cabecaY + raio * 0.45,
        raio * 0.34,
        raio * 0.26,
        0,
        0,
        Math.PI * 2,
      );
      ctx.fill();
    }

    ctx.fillStyle = ROSA;
    ctx.beginPath();
    ctx.moveTo(cx, cabecaY + raio * 0.42);
    ctx.lineTo(cx - raio * 0.16, cabecaY + raio * 0.2);
    ctx.lineTo(cx + raio * 0.16, cabecaY + raio * 0.2);
    ctx.closePath();
    ctx.fill();

    ctx.strokeStyle = PELO_ESCURO;
    ctx.lineWidth = Math.max(1.2, raio * 0.06);
    ctx.beginPath();
    ctx.moveTo(cx, cabecaY + raio * 0.42);
    ctx.lineTo(cx, cabecaY + raio * 0.56);
    ctx.stroke();
    for (const lado of [-1, 1]) {
      ctx.beginPath();
      ctx.arc(
        cx + lado * raio * 0.18,
        cabecaY + raio * 0.5,
        raio * 0.19,
        lado > 0 ? Math.PI * 0.55 : Math.PI * 0.05,
        lado > 0 ? Math.PI * 0.95 : Math.PI * 0.45,
      );
      ctx.stroke();
    }

    rodape(
      ctx,
      L,
      A,
      ok,
      'Os bigodes tocam as bordas: cabe por um triz ✔',
      cabe
        ? 'Folga demais — aperte até os bigodes tocarem.'
        : 'Os bigodes dobram: ele sabe que não cabe.',
    );
  }

  const base = criarCanvas2d(canvas, {
    aoQuadro: (ctx, { L, A }) => desenhar(ctx, L, A),
  });

  return {
    aplicar(novo) {
      estado = novo;
    },
    redimensionar: base.redimensionar,
    pausar: base.pausar,
    retomar: base.retomar,
    destruir: base.destruir,
  };
};

export default bigodeGato;
